<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/bootstrap.php';use App\Core\Auth;use App\Core\Csrf;use App\Core\Database;use App\Services\CouncilResultIdentityService;
Auth::requirePermission('competitors.edit');$pdo=Database::connection();$id=(int)($_GET['id']??$_POST['id']??0);$row=null;$error='';if($id){$s=$pdo->prepare('SELECT * FROM bdc_wdc_identities WHERE id=:id');$s->execute(['id'=>$id]);$row=$s->fetch();if(!$row){http_response_code(404);exit('WDC competitor not found.');}}
if($_SERVER['REQUEST_METHOD']==='POST'){try{if(!Csrf::verify($_POST['_csrf']??null))throw new RuntimeException('Invalid security token.');$name=trim((string)($_POST['display_name']??''));$type=(string)($_POST['entry_type']??'solo');$country=trim((string)($_POST['country']??''));$photo=trim((string)($_POST['photo_url']??''));$status=(string)($_POST['status']??'active');if($name==='')throw new RuntimeException('Name is required.');if(!in_array($type,['solo','couple','duo','pro_am','team'],true))throw new RuntimeException('Invalid entry type.');if(!in_array($status,['active','archived'],true))throw new RuntimeException('Invalid status.');if($id){$normal=function_exists('mb_strtolower')?mb_strtolower($name,'UTF-8'):strtolower($name);$normal=trim((string)preg_replace('/[^\pL\pN]+/u',' ',$normal));$pdo->prepare('UPDATE bdc_wdc_identities SET display_name=:name,normalised_name=:normal,country=NULLIF(:country,\'\'),photo_url=NULLIF(:photo,\'\'),status=:status WHERE id=:id')->execute(['name'=>$name,'normal'=>$normal,'country'=>$country,'photo'=>$photo,'status'=>$status,'id'=>$id]);}else{$identity=CouncilResultIdentityService::wdcIdentityForEntry($pdo,$type,$name,null);$id=(int)$identity['id'];$pdo->prepare('UPDATE bdc_wdc_identities SET country=NULLIF(:country,\'\'),photo_url=NULLIF(:photo,\'\'),status=:status WHERE id=:id')->execute(['country'=>$country,'photo'=>$photo,'status'=>$status,'id'=>$id]);}header('Location: competitors.php#wdc-'.$id,true,303);exit;}catch(Throwable $e){$error=$e->getMessage();}}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=$id?'Edit':'Add'?> Dance Cup Competitor</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-4" style="max-width:760px"><div class="d-flex justify-content-between mb-3"><h1 class="h3"><?=$id?'Edit':'Add'?> Dance Cup Competitor</h1><a class="btn btn-outline-dark" href="competitors.php">Back</a></div><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><form method="post" class="card border-0 shadow-sm"><div class="card-body row g-3"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="id" value="<?=$id?>"><?php if($row):?><div class="col-12"><label class="form-label">WDC ID</label><input class="form-control" value="<?=e($row['identity_code'])?>" readonly><div class="form-text">Permanent and cannot be changed.</div></div><?php endif;?><div class="col-md-8"><label class="form-label">Competitor, couple or team name</label><input class="form-control" name="display_name" value="<?=e($row['display_name']??'')?>" required></div><div class="col-md-4"><label class="form-label">Entry type</label><select class="form-select" name="entry_type" <?=$row?'disabled':''?>><?php foreach(['solo','couple','duo','pro_am','team'] as $v):?><option value="<?=$v?>" <?=($row['entry_type']??'solo')===$v?'selected':''?>><?=e(ucwords(str_replace('_',' ',$v)))?></option><?php endforeach;?></select><?php if($row):?><input type="hidden" name="entry_type" value="<?=e($row['entry_type'])?>"><?php endif;?></div><div class="col-md-6"><label class="form-label">Country</label><input class="form-control" name="country" value="<?=e($row['country']??'')?>"></div><div class="col-md-6"><label class="form-label">Status</label><select class="form-select" name="status"><option value="active" <?=($row['status']??'active')==='active'?'selected':''?>>Active</option><option value="archived" <?=($row['status']??'')==='archived'?'selected':''?>>Archived</option></select></div><div class="col-12"><label class="form-label">Photo URL</label><input class="form-control" name="photo_url" value="<?=e($row['photo_url']??'')?>"></div></div><div class="card-footer bg-white text-end"><button class="btn btn-primary">Save Competitor</button></div></form></main></body></html>
